"""Pack the production battle strip generated by render-sixth-preview.js."""
from pathlib import Path
from PIL import Image

OUT = Path(__file__).resolve().parents[1] / 'docs/previews'
strip = Image.open(OUT/'chapter-06-mask-animation-strip.png').convert('RGB')
frames = [strip.crop((0,i*324,1152,(i+1)*324)).resize((960,270),Image.Resampling.LANCZOS) for i in range(40)]
frames[0].save(OUT/'chapter-06-mask-battle.gif',save_all=True,append_images=frames[1:],duration=60,loop=0,disposal=2)
frames[23].save(OUT/'chapter-06-mask-battle.png')
print('Saved chapter-06-mask-battle.gif from 40 production battle frames.')
